package main

import("context";"errors";"strings")
type CoreRouterIntegration struct{Adapter CoreRouterAdapter}
func(i CoreRouterIntegration)Inspect(ctx context.Context,node CoreRouterNode)(CoreRouterHealth,[]CoreRouterPeerState,error){if ctx==nil{return CoreRouterHealth{},nil,errors.New("context_required")};if i.Adapter==nil{return CoreRouterHealth{},nil,errors.New("core_router_adapter_required")};if err:=ValidateCoreRouterNode(node);err!=nil{return CoreRouterHealth{},nil,err};h,err:=i.Adapter.Health(ctx,node);if err!=nil{return CoreRouterHealth{},nil,err};peers,err:=i.Adapter.Peers(ctx,node);if err!=nil{return CoreRouterHealth{},nil,err};return h,peers,nil}
func(i CoreRouterIntegration)Plan(ctx context.Context,node CoreRouterNode,intent RouteChangeIntent)(RouteChangePlan,error){if ctx==nil{return RouteChangePlan{},errors.New("context_required")};if i.Adapter==nil{return RouteChangePlan{},errors.New("core_router_adapter_required")};if err:=ValidateCoreRouterNode(node);err!=nil{return RouteChangePlan{},err};if err:=ctx.Err();err!=nil{return RouteChangePlan{},err};return i.Adapter.PlanRouteChange(ctx,node,intent)}
func RequireApprovedRoutePlan(plan RouteChangePlan,approvalID string)error{if !plan.Allowed{return errors.New("route_plan_not_allowed")};approvalID=strings.TrimSpace(approvalID);if !plan.RequiresApproval||approvalID==""||len(approvalID)>256{return errors.New("approval_required")};if !plan.PreChangeSnapshot||!plan.PostChangeVerify||!plan.RollbackWhenSafe{return errors.New("route_safety_gates_incomplete")};return nil}
